    : 'NOT VERIFIED — tests were not run.';
  const typecheckLine = result.typecheckRun
    ? (result.testsPassed ? 'PASS — typecheck completed.' : 'FAIL — typecheck reported errors.')
    : 'NOT VERIFIED — typecheck was not run.';

