// Commit + deploy the CHAT ↔ WORKER SYNC wiring fix
import { readFileSync } from 'node:fs';
import { gzipSync } from 'node:zlib';

const OWNER_EMAIL = "iperez4242@gmail.com";
const BASE = "https://api.ivxholding.com";

// 1. Mint fresh owner token
const lm = await fetch(BASE + "/api/ivx/owner-passwordless-login", {
  method: "POST",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ email: OWNER_EMAIL }),
});
const lmj = await lm.json();
if (!lmj.accessToken) {
  console.error("FAILED to mint owner token:", JSON.stringify(lmj).slice(0, 300));
  process.exit(1);
}
const token = lmj.accessToken;
await Bun.file("/tmp/owner_at").write(token);
console.log("Owner token minted, len=" + token.length);

// 2. Read + encode the 2 changed files
const ownerAiPath = "backend/api/ivx-owner-ai.ts";
const answerFmtPath = "backend/services/ivx-senior-developer-answer-format.ts";

const ownerAiRaw = readFileSync("/home/user/rork-app/" + ownerAiPath);
const ownerAiGzB64 = gzipSync(ownerAiRaw).toString("base64");
console.log("ivx-owner-ai.ts: " + ownerAiRaw.length + " bytes → gzip-base64 " + ownerAiGzB64.length + " chars");

const answerFmtRaw = readFileSync("/home/user/rork-app/" + answerFmtPath);
const answerFmtPlain = answerAiRaw.toString("utf8");
console.log("ivx-senior-developer-answer-format.ts: " + answerFmtRaw.length + " bytes (plain text)");

// 3. Commit ivx-owner-ai.ts via gzip-base64 (large file → WAF-safe)
const COMMIT_MSG = "feat(ivx-chat): wire self_developer chat branch to persistent worker queue

Route IVX IA Chat developer-execution requests through the durable worker
queue (enqueueOrAttachSeniorDeveloperJob) instead of calling
runIVXSeniorDeveloperTask inline. This closes the long-standing gap where
chat ran real work but created NO persistent job.

Now every developer-execution request from IVX IA Chat creates exactly one
durable job with:
- real taskId returned to chat
- dashboard sync (reads from same queue)
- restart survival (durable store + GitHub side-branch ledger)
- no duplicates (per-owner single-flight + attach)
- live progress (bounded poll renders real stage/progress)

The worker's drain loop calls the SAME runIVXSeniorDeveloperTask pipeline
with phase callbacks that update the job stage in real time. Chat renders
the strict execution answer from the persisted IVXWorkerJob via the new
buildSeniorDeveloperWorkerJobAnswer renderer.";

console.log("\n=== COMMIT 1: ivx-owner-ai.ts (gzip-base64) ===");
const c1 = await fetch(BASE + "/api/ivx/developer-deploy/action", {
  method: "POST",
  headers: { "Content-Type": "application/json", Authorization: "Bearer " + token },
  body: JSON.stringify({
    action: "github_commit_file",
    input: {
      path: ownerAiPath,
      content: ownerAiGzB64,
      contentEncoding: "gzip-base64",
      message: COMMIT_MSG,
    },
    confirm: true,
    confirmText: "CONFIRM_IVX_GITHUB_WRITE",
  }),
});
const c1j = await c1.json();
console.log("status=" + c1.status + " commitSha=" + (c1j.commitSha || c1j.sha || "NONE"));
console.log("response: " + JSON.stringify(c1j).slice(0, 400));
if (c1.status >= 400 || (!c1j.commitSha && !c1j.sha && !c1j.ok)) {
  console.error("COMMIT 1 FAILED");
  process.exit(1);
}

// 4. Commit ivx-senior-developer-answer-format.ts (small → plain text)
console.log("\n=== COMMIT 2: ivx-senior-developer-answer-format.ts (plain) ===");
const c2 = await fetch(BASE + "/api/ivx/developer-deploy/action", {
  method: "POST",
  headers: { "Content-Type": "application/json", Authorization: "Bearer " + token },
  body: JSON.stringify({
    action: "github_commit_file",
    input: {
      path: answerFmtPath,
      content: answerFmtPlain,
      message: "feat(ivx-answer-format): add buildSeniorDeveloperWorkerJobAnswer renderer for worker-queue jobs",
    },
    confirm: true,
    confirmText: "CONFIRM_IVX_GITHUB_WRITE",
  }),
});
const c2j = await c2.json();
console.log("status=" + c2.status + " commitSha=" + (c2j.commitSha || c2j.sha || "NONE"));
console.log("response: " + JSON.stringify(c2j).slice(0, 400));
if (c2.status >= 400 || (!c2j.commitSha && !c2j.sha && !c2j.ok)) {
  console.error("COMMIT 2 FAILED");
  process.exit(1);
}

// 5. Trigger Render deploy
console.log("\n=== RENDER DEPLOY ===");
const d = await fetch(BASE + "/api/ivx/developer-deploy/action", {
  method: "POST",
  headers: { "Content-Type": "application/json", Authorization: "Bearer " + token },
  body: JSON.stringify({
    action: "render_trigger_deploy",
    input: {},
    confirm: true,
    confirmText: "CONFIRM_IVX_RENDER_DEPLOY",
  }),
});
const dj = await d.json();
console.log("status=" + d.status + " deployId=" + (dj.deployId || "NONE"));
console.log("response: " + JSON.stringify(dj).slice(0, 400));

console.log("\n=== DONE — poll /api/tool/render-status for LIVE ===");

