// FINAL E2E TEST: IVX IA Chat → autonomous worker → persistent job → verified evidence
// Test prompt (from the mandate): "Audit the IVX health endpoint, verify the live
// GitHub commit, run the backend smoke tests, and return verified evidence. Do not deploy."
const OWNER_EMAIL = "iperez4242@gmail.com";
const BASE = "https://api.ivxholding.com";
const TEST_PROMPT = "Audit the IVX health endpoint, verify the live GitHub commit, run the backend smoke tests, and return verified evidence. Do not deploy.";

// 1. Mint fresh owner token (chat endpoint requires owner bearer)
const lm = await fetch(BASE + "/api/ivx/owner-passwordless-login", {
  method: "POST",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ email: OWNER_EMAIL }),
});
const lmj = await lm.json();
if (!lmj.accessToken) {
  console.error("FAILED to mint owner token:", JSON.stringify(lmj).slice(0, 300));
  process.exit(1);
}
const token = lmj.accessToken;
await Bun.file("/tmp/owner_at").write(token);
console.log("Owner token minted, len=" + token.length);

// 2. Submit the test prompt to IVX IA Chat (POST /api/ivx/owner-ai)
const requestId = "e2e-chat-worker-sync-" + Date.now();
const conversationId = "e2e-chat-worker-sync-" + Date.now();
console.log("\n=== SUBMITTING TEST PROMPT TO IVX IA CHAT ===");
console.log("requestId: " + requestId);
console.log("prompt: " + TEST_PROMPT);

const t0 = Date.now();
const chatRes = await fetch(BASE + "/api/ivx/owner-ai", {
  method: "POST",
  headers: { "Content-Type": "application/json", Authorization: "Bearer " + token },
  body: JSON.stringify({
    message: TEST_PROMPT,
    conversationId,
    requestId,
    email: OWNER_EMAIL,
  }),
});
const elapsed = Date.now() - t0;
const chatText = await chatRes.text();
console.log("\nHTTP status: " + chatRes.status + " (elapsed " + elapsed + "ms)");
let chatJson: any = null;
try { chatJson = JSON.parse(chatText); } catch {}

// 3. Extract the task ID from the chat answer
const answer = chatJson?.answer || chatText;
console.log("\n=== CHAT ANSWER (first 2000 chars) ===");
console.log(answer.slice(0, 2000));

// Look for TASK ID: in the answer (the new renderer adds it)
const taskIdMatch = answer.match(/TASK ID:\s*\n?(ivx-worker-[a-f0-9-]+)/i);
const taskId = taskIdMatch ? taskIdMatch[1] : null;
console.log("\n=== EXTRACTED TASK ID ===");
console.log("taskId: " + taskId);

if (!taskId) {
  console.error("\nFAILED: no TASK ID found in chat answer. The wiring may not have created a persistent job.");
  console.error("Full answer saved to /tmp/e2e-chat-answer.txt");
  await Bun.file("/tmp/e2e-chat-answer.txt").write(answer);
  process.exit(1);
}

// 4. Verify the task exists in the persistent worker queue
console.log("\n=== VERIFY TASK IN PERSISTENT WORKER QUEUE ===");
const jobRes = await fetch(BASE + "/api/ivx/senior-developer/worker/jobs/" + taskId, {
  headers: { Authorization: "Bearer " + token },
});
const jobJson = await jobRes.json();
console.log("GET /api/ivx/senior-developer/worker/jobs/" + taskId);
console.log("HTTP status: " + jobRes.status);
console.log("job.status: " + jobJson?.job?.status);
console.log("job.stage: " + jobJson?.job?.stage);
console.log("job.progressPercent: " + jobJson?.job?.progressPercent);
console.log("job.result.finalStatus: " + jobJson?.job?.result?.finalStatus);
console.log("job.result.commitSha: " + jobJson?.job?.result?.commitSha);
console.log("job.result.healthOk: " + jobJson?.job?.result?.healthOk);
console.log("job.result.testsRun: " + jobJson?.job?.result?.testsRun);
console.log("job.result.testsPassed: " + jobJson?.job?.result?.testsPassed);

// 5. Verify the task appears in the dashboard list (GET /api/ivx/senior-developer/worker/jobs)
console.log("\n=== VERIFY TASK IN DASHBOARD LIST ===");
const listRes = await fetch(BASE + "/api/ivx/senior-developer/worker/jobs", {
  headers: { Authorization: "Bearer " + token },
});
const listJson = await listRes.json();
const jobs = listJson?.jobs || [];
const foundInList = jobs.find((j: any) => j.jobId === taskId);
console.log("Total jobs in dashboard: " + jobs.length);
console.log("Task found in dashboard list: " + (foundInList ? "YES" : "NO"));
if (foundInList) {
  console.log("  dashboard status: " + foundInList.status + " stage: " + foundInList.stage);
}

// 6. Verify no duplicate task was created (submit the same prompt again, should attach)
console.log("\n=== VERIFY NO DUPLICATE (resubmit same prompt) ===");
const dupRes = await fetch(BASE + "/api/ivx/senior-developer/worker/jobs", {
  method: "POST",
  headers: { "Content-Type": "application/json", Authorization: "Bearer " + token },
  body: JSON.stringify({ goal: TEST_PROMPT }),
});
const dupJson = await dupRes.json();
console.log("Resubmit HTTP status: " + dupRes.status);
console.log("attached: " + dupJson.attached);
console.log("activeJobId: " + dupJson.activeJobId);
console.log("jobId: " + dupJson.jobId);
const noDuplicate = dupJson.attached === true && dupJson.activeJobId === taskId;
console.log("NO DUPLICATE (attached to same job): " + noDuplicate);

// 7. Final evidence
const evidence = {
  testTimestamp: new Date().toISOString(),
  testPrompt: TEST_PROMPT,
  chatHttpStatus: chatRes.status,
  chatElapsedMs: elapsed,
  taskId,
  taskInPersistentQueue: jobRes.status === 200 && !!jobJson?.job,
  taskInDashboardList: !!foundInList,
  noDuplicateOnResubmit: noDuplicate,
  jobStatus: jobJson?.job?.status,
  jobStage: jobJson?.job?.stage,
  jobProgress: jobJson?.job?.progressPercent,
  jobResult: jobJson?.job?.result ? {
    finalStatus: jobJson.job.result.finalStatus,
    commitSha: jobJson.job.result.commitSha,
    healthOk: jobJson.job.result.healthOk,
    testsRun: jobJson.job.result.testsRun,
    testsPassed: jobJson.job.result.testsPassed,
    changedFiles: jobJson.job.result.changedFiles,
    error: jobJson.job.result.error,
  } : null,
  chatAnswerPreview: answer.slice(0, 800),
};
await Bun.file("/tmp/e2e-chat-worker-sync-evidence.json").write(JSON.stringify(evidence, null, 2));
console.log("\n=== FINAL E2E EVIDENCE ===");
console.log(JSON.stringify(evidence, null, 2));

const allPass = evidence.taskInPersistentQueue && evidence.taskInDashboardList && evidence.noDuplicateOnResubmit;
console.log("\n=== E2E TEST RESULT: " + (allPass ? "PASS" : "FAIL") + " ===");

