// Commit + deploy the chat→worker router fix (developer_executor OR self_developer)
import { readFileSync } from 'node:fs';
import { gzipSync } from 'node:zlib';

const OWNER_EMAIL = "iperez4242@gmail.com";
const BASE = "https://api.ivxholding.com";

// 1. Mint fresh owner token
const lm = await fetch(BASE + "/api/ivx/owner-passwordless-login", {
  method: "POST",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ email: OWNER_EMAIL }),
});
const lmj = await lm.json();
if (!lmj.accessToken) {
  console.error("FAILED to mint owner token:", JSON.stringify(lmj).slice(0, 300));
  process.exit(1);
}
const token = lmj.accessToken;
await Bun.file("/tmp/owner_at").write(token);
console.log("Owner token minted, len=" + token.length);

// 2. Read + gzip ivx-owner-ai.ts (large file)
const filePath = "backend/api/ivx-owner-ai.ts";
const raw = readFileSync("/home/user/rork-app/" + filePath);
const gzB64 = gzipSync(raw).toString("base64");
console.log("ivx-owner-ai.ts: " + raw.length + " bytes → gzip-base64 " + gzB64.length + " chars");

const COMMIT_MSG = `fix(ivx-chat): trigger worker queue on unified router developer_executor branch

The chat→worker sync wiring (commit dda3e86c) gated the persistent worker
queue path on plannerDecision.route === 'self_developer' only. But the
unified 5-branch router (routeIVXChatIntent) classifies audit/verify/
smoke-test/build/fix/deploy/QA/recovery/database/production-verification
prompts as developer_executor even when the legacy keyword planner does
not map them to self_developer.

Result: the test prompt "Audit the IVX health endpoint, verify the live
GitHub commit, run the backend smoke tests" was classified as
developer_executor by the unified router but NOT self_developer by the
legacy planner → fell through to the narrative GPT path → no persistent
job created → no TASK ID returned to chat.

Fix: trigger the persistent worker queue on EITHER the legacy planner's
self_developer route OR the unified router's developer_executor branch.
Log the routing reconciliation when the unified router fires but the
legacy planner did not, so the audit trail is explicit.`;

console.log("\n=== COMMIT: ivx-owner-ai.ts (gzip-base64) ===");
const c = await fetch(BASE + "/api/ivx/developer-deploy/action", {
  method: "POST",
  headers: { "Content-Type": "application/json", Authorization: "Bearer " + token },
  body: JSON.stringify({
    action: "github_commit_file",
    input: {
      path: filePath,
      content: gzB64,
      contentEncoding: "gzip-base64",
      message: COMMIT_MSG,
    },
    confirm: true,
    confirmText: "CONFIRM_IVX_GITHUB_WRITE",
  }),
});
const cj = await c.json();
console.log("status=" + c.status);
const commitSha = cj.commitSha || cj.sha || (cj.result && cj.result.commitSha) || "NONE";
console.log("commitSha=" + commitSha);
console.log("response: " + JSON.stringify(cj).slice(0, 400));
if (c.status >= 400 || commitSha === "NONE") {
  console.error("COMMIT FAILED");
  process.exit(1);
}

// 3. Trigger Render deploy
console.log("\n=== RENDER DEPLOY ===");
const d = await fetch(BASE + "/api/ivx/developer-deploy/action", {
  method: "POST",
  headers: { "Content-Type": "application/json", Authorization: "Bearer " + token },
  body: JSON.stringify({
    action: "render_trigger_deploy",
    input: {},
    confirm: true,
    confirmText: "CONFIRM_IVX_RENDER_DEPLOY",
  }),
});
const dj = await d.json();
console.log("status=" + d.status + " response: " + JSON.stringify(dj).slice(0, 300));

console.log("\n=== DONE — poll /api/tool/render-status for LIVE ===");
await Bun.file("/tmp/last-commit-sha.txt").write(commitSha);

