   229|      `COMMANDS RUN:\n(phase: ${job.stage} — ${job.stageDetail})`,
   230|      'TEST RESULT:\nNOT VERIFIED — tests have not completed.',
   231|      'TYPECHECK RESULT:\nNOT VERIFIED — typecheck has not completed.',
   232|      `STATUS:\nRUNNING (${job.status}, ${job.progressPercent}%)`,
   233|      `PROOF:\nLive progress from durable queue. stage=${job.stage} progress=${job.progressPercent}% detail="${job.stageDetail}" attempts=${job.attempts}`,
   234|      `TASK ID:\n${job.jobId}`,
   235|      `STATUS URL:\n/api/ivx/senior-developer/worker/jobs/${job.jobId}`,
   236|    ].join('\n\n');
   237|  }
   238|
