   240|  const changedFiles = result.changedFiles.length > 0
   241|    ? result.changedFiles.join('\n')
   242|    : (result.finalStatus === 'BLOCKED'
   243|        ? 'BLOCKED — I do not have code write access.'
   244|        : 'NO CODE CHANGED — no development was completed.');
