  method: "POST",
  headers: { "Content-Type": "application/json", Authorization: "Bearer " + token },
  body: JSON.stringify({
    action: "github_commit_file",
    input: { path: filePath, content: gzB64, contentEncoding: "gzip-base64", message: COMMIT_MSG },
